args.sql:
SELECT ROUND(CAST(MAX(h.residentcount) AS numeric) / CAST(MIN(p.dwelling_specs->>'Room_Count') AS numeric), 2)
FROM households h
JOIN properties p ON h.housenum = p.houselink;

